// Digi's Crafting and Automation: Auto Processing, Auto Oven, Auto Cooking Station, Auto Fermenter, Fermenter Timer, Sap Timer, Craft Batch, Shift Fill From Storage, Recycle Tab, Auto Repair, Restyle Items, Cooking Mastery, Cookbook, Craft Storage Count, Recipe Sort and Search.
// One plugin and one settings file for all of them: F1 shows a switch per sub-mod at the top, then each sub-mod's
// settings under its name. Generated by make_combined.py; the sub-mods' code is in Modules/.
using BepInEx;
using DigiCore;

namespace DigiCrafting
{
    [BepInPlugin(Guid, Name, Version)]
    [BepInDependency("LuminairPrime.valheim.localcraftfromstorageprime", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("Searica.Valheim.TerrainTools", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ValheimLegends", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("cdev.equipmentslots", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("com.alan.bettersmelter", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("ishid4.mods.betterarchery", BepInDependency.DependencyFlags.SoftDependency)]
    [BepInDependency("randyknapp.mods.epicloot", BepInDependency.DependencyFlags.SoftDependency)]
    public class Plugin : DigiPlugin
    {
        public const string Guid = "digi.valheim.crafting";
        public const string Name = "Digi's Crafting and Automation";
        public const string Version = "1.0.33";

        protected override ModuleInfo[] Modules { get; } =
        {
            new ModuleInfo(typeof(global::AutoProcessing.Plugin), "Auto Processing", "digi.valheim.autoprocessing", "Smelters, kilns (also the frigid kiln), spinning wheels, eitr refineries and windmills fill themselves from nearby chests and store their output; sap extractors and beehives too.", null, true),
            new ModuleInfo(typeof(global::AutoOven.Plugin), "Auto Oven", "digi.valheim.autooven", "Ovens and the frost foundry fill, fuel and empty themselves using nearby chests; Shift+E adds max fuel.", null, true),
            new ModuleInfo(typeof(global::AutoFuel.Plugin), "Auto Fuel", "digi.valheim.autofuel", "Fires, torches, sconces, braziers, lanterns and the hot tub refill their own fuel from chests up to 100 m away; a switch per kind.", null, true),
            new ModuleInfo(typeof(global::AutoCookingStation.Plugin), "Auto Cooking Station", "digi.valheim.autocookingstation", "Iron and wooden cooking stations fill and empty themselves using nearby chests, with a switch per item and separate input and output ranges.", null, true),
            new ModuleInfo(typeof(global::AutoFermenter.Plugin), "Auto Fermenter", "digi.valheim.autofermenter", "Fermenters refill with mead base and tap finished mead into a chest by themselves.", null, true),
            new ModuleInfo(typeof(global::FermenterTimer.Plugin), "Fermenter Timer", "digi.valheim.fermentertimer", "Shows how long a fermenter still needs and what it will give.", null, true),
            new ModuleInfo(typeof(global::SapTimer.Plugin), "Sap Timer", "digi.valheim.saptimer", "Shows how much sap an ancient root holds and when a sap extractor collects its next sap.", null, true),
            new ModuleInfo(typeof(global::CraftBatch.Plugin), "Craft Batch", "digi.valheim.craftbatch", "Ctrl+Shift+Craft makes 20 at once.", null, true),
            new ModuleInfo(typeof(global::CraftFromChests.Plugin), "Craft From Chests", "digi.valheim.craftfromchests", "Crafting, upgrading, building and filling fires and stations use what lies in the chests around you; a checkbox per chest; replaces Local Craft From Storage.", null, true),
            new ModuleInfo(typeof(global::RecycleTab.Plugin), "Recycle Tab", "digi.valheim.recycletab", "A Recycle tab at crafting stations to get materials back from items you don't need.", null, true),
            new ModuleInfo(typeof(global::CraftSpeed.Plugin), "Craft Speed", "digi.valheim.craftspeed", "Set how fast crafting goes at the stations, and on its own how fast recycling goes in the Recycle tab.", null, true),
            new ModuleInfo(typeof(global::AutoRepair.Plugin), "Auto Repair", "digi.valheim.autorepair", "Opening a crafting station repairs all your gear at once.", null, true),
            new ModuleInfo(typeof(global::RestyleItems.Plugin), "Restyle Items", "digi.valheim.restyleitems", "Change the style of an item you already own at a station.", null, true),
            new ModuleInfo(typeof(global::CookingMastery.Plugin), "Cooking Mastery", "digi.valheim.cookingmastery", "Your Cooking skill makes all food stronger and longer lasting.", null, true),
            new ModuleInfo(typeof(global::RecipeSort.Plugin), "Recipe Sort and Search", "digi.valheim.recipesort", "Crafting stations list their recipes by kind, then biome, then A-Z, with a search box under the list.", null, true),
            new ModuleInfo(typeof(global::Cookbook.Plugin), "Cookbook", "digi.valheim.cookbook", "Press K for a book of every food you found: stats, where it is made and from what, sortable.", null, true),
        };
    }
}
